-- Arbeitsrecht Berufsbildung > Betriebswirtschaftliche Grundlagen > Gewinnermittlung > Einnahmen-Überschuss-Rechnung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird bei der Einnahmen-Überschuss-Rechnung der Gewinn eines IT-Betriebs durch Einnahmen minus Ausgaben ermittelt?', 2, '[{"text": "Ja", "correct": true, "because": "Die EÜR berechnet den Gewinn als Einnahmen minus Ausgaben"}, {"text": "Nein", "correct": false, "because": "Das ist die Grundlage der EÜR"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der EÜR eines IT-Betriebs Abschreibungen berücksichtigt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Abschreibungen sind in der EÜR nicht üblich"}, {"text": "Ja", "correct": false, "because": "EÜR basiert auf Zu- und Abflüssen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb die EÜR nutzen, wenn er als Einzelunternehmer geführt wird?', 2, '[{"text": "Ja", "correct": true, "because": "Einzelunternehmer dürfen die EÜR anwenden"}, {"text": "Nein", "correct": false, "because": "EÜR ist für Einzelunternehmer geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind bei der EÜR eines IT-Betriebs nur die tatsächlich eingegangenen Einnahmen relevant?', 2, '[{"text": "Ja", "correct": true, "because": "EÜR basiert auf dem Zuflussprinzip"}, {"text": "Nein", "correct": false, "because": "Nur Zuflüsse zählen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Betrieb bei der EÜR eine Bilanz erstellen?', 2, '[{"text": "Nein", "correct": true, "because": "EÜR erfordert keine Bilanz, nur Einnahmen und Ausgaben"}, {"text": "Ja", "correct": false, "because": "Bilanz ist nicht Teil der EÜR"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wie wird der Gewinn eines IT-Betriebs in der Einnahmen-Überschuss-Rechnung ermittelt?', 2, '[{"text": "Einnahmen minus Ausgaben", "correct": true, "because": "Grundprinzip der EÜR"}, {"text": "Einnahmen plus Ausgaben", "correct": false, "because": "Falsche Berechnung"}, {"text": "Nur Einnahmen", "correct": false, "because": "Ausgaben werden abgezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip liegt der EÜR eines IT-Betriebs zugrunde?', 3, '[{"text": "Zufluss-Abfluss-Prinzip", "correct": true, "because": "EÜR berücksichtigt tatsächliche Zahlungen"}, {"text": "Ist-Versteuerung", "correct": false, "because": "Nicht relevant für EÜR"}, {"text": "Soll-Versteuerung", "correct": false, "because": "Gilt für Bilanzierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unternehmensform darf die EÜR für einen IT-Betrieb nutzen?', 3, '[{"text": "Einzelunternehmer", "correct": true, "because": "Einzelunternehmer sind zur EÜR berechtigt"}, {"text": "GmbH", "correct": false, "because": "GmbH muss bilanzieren"}, {"text": "AG", "correct": false, "because": "AG muss bilanzieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einnahmen werden in der EÜR eines IT-Betriebs berücksichtigt?', 2, '[{"text": "Tatsächlich eingegangene Einnahmen", "correct": true, "because": "Zuflussprinzip der EÜR"}, {"text": "Geplante Einnahmen", "correct": false, "because": "Nur Zuflüsse zählen"}, {"text": "Zukünftige Einnahmen", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil der EÜR für einen IT-Betrieb?', 3, '[{"text": "Einfache Erstellung", "correct": true, "because": "EÜR ist weniger komplex als Bilanzierung"}, {"text": "Hohe Genauigkeit der Gewinnermittlung", "correct": false, "because": "EÜR ist weniger detailliert"}, {"text": "Pflicht zur Bilanzierung", "correct": false, "because": "EÜR ersetzt die Bilanz"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Einnahmen-Überschuss-Rechnung für einen IT-Betrieb?', 4, '[{"text": "Einnahmen minus Ausgaben", "correct": true, "because": "Grundprinzip der EÜR"}, {"text": "Zufluss-Abfluss-Prinzip", "correct": true, "because": "Nur tatsächliche Zahlungen zählen"}, {"text": "Bilanzierung erforderlich", "correct": false, "because": "EÜR ersetzt die Bilanz"}, {"text": "Einfache Gewinnermittlung", "correct": true, "because": "EÜR ist weniger komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ausgaben werden in der EÜR eines IT-Betriebs berücksichtigt?', 3, '[{"text": "Tatsächlich getätigte Ausgaben", "correct": true, "because": "Abflussprinzip der EÜR"}, {"text": "Betriebsausgaben wie Miete", "correct": true, "because": "Relevante Ausgaben werden erfasst"}, {"text": "Geplante Ausgaben", "correct": false, "because": "Nur Abflüsse zählen"}, {"text": "Werbungskosten", "correct": true, "because": "Steuerlich absetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unternehmen dürfen die EÜR für einen IT-Betrieb nutzen?', 4, '[{"text": "Einzelunternehmer", "correct": true, "because": "EÜR für Einzelunternehmer geeignet"}, {"text": "Freiberufler", "correct": true, "because": "Freiberufler dürfen EÜR nutzen"}, {"text": "Kapitalgesellschaften", "correct": false, "because": "Müssen bilanzieren"}, {"text": "Personengesellschaften unter Grenze", "correct": true, "because": "Bis zu Umsatzgrenzen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die EÜR für einen IT-Betrieb?', 3, '[{"text": "Einfache Buchführung", "correct": true, "because": "Weniger aufwendig als Bilanz"}, {"text": "Geringerer Verwaltungsaufwand", "correct": true, "because": "EÜR ist unkompliziert"}, {"text": "Detaillierte Vermögensübersicht", "correct": false, "because": "Keine Bilanz erforderlich"}, {"text": "Steuerliche Vereinfachung", "correct": true, "because": "EÜR ist steuerlich akzeptiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die EÜR von der Bilanzierung für einen IT-Betrieb?', 3, '[{"text": "EÜR basiert auf Zu- und Abflüssen", "correct": true, "because": "Zufluss-Abfluss-Prinzip"}, {"text": "Bilanzierung berücksichtigt Vermögen", "correct": true, "because": "Bilanz zeigt Vermögenslage"}, {"text": "EÜR ist komplexer", "correct": false, "because": "EÜR ist einfacher"}, {"text": "Bilanzierung ist für Einzelunternehmer", "correct": false, "because": "Bilanz für Kapitalgesellschaften"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die EÜR ermittelt den Gewinn durch Einnahmen minus Ausgaben. b) Abschreibungen sind in der EÜR Pflicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einnahmen minus Ausgaben ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Einzelunternehmer können die EÜR nutzen. b) Die EÜR berücksichtigt tatsächliche Zahlungen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Einzelunternehmer und Zuflussprinzip"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die EÜR erfordert keine Bilanz. b) Kapitalgesellschaften nutzen die EÜR.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Bilanz, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die EÜR ist einfacher als die Bilanzierung. b) Geplante Einnahmen werden in der EÜR erfasst.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einfacher ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die EÜR basiert auf dem Zuflussprinzip. b) Eine GmbH darf die EÜR nutzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zuflussprinzip ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

